// src/app/messages/[userId]/page.jsx
"use client";

import { useEffect, useState } from "react";
import { useRouter, useParams } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";
import api from "@/services/api";
import { Video, Phone, X } from "lucide-react";

export default function ChatPage() {
  const { user, loading } = useAuth();
  const socket = useSocket();
  const router = useRouter();
  const { userId } = useParams();

  const [receiver, setReceiver] = useState(null);
  const [showCallPopup, setShowCallPopup] = useState(false);
  const [incomingCall, setIncomingCall] = useState(null);

  useEffect(() => {
    if (!loading && !user) router.push("/login");
  }, [loading, user, router]);

  useEffect(() => {
    async function fetchUser() {
      try {
        const res = await api.get(`/api/users/profile/${userId}`);
        setReceiver(res.data);
      } catch (err) {
        console.error("Failed to load user:", err);
      }
    }
    if (userId) fetchUser();
  }, [userId]);

  // Handle incoming call
  useEffect(() => {
    if (!socket || !user) return;

    socket.on("incoming_call", ({ fromUser }) => {
      setIncomingCall(fromUser);
      setShowCallPopup(true);
    });

    return () => {
      socket.off("incoming_call");
    };
  }, [socket, user]);

  const startCall = () => {
    if (socket && user && receiver) {
      socket.emit("start_call", {
        from: user.id,
        to: receiver.id,
      });
    }
  };

  const acceptCall = () => {
    setShowCallPopup(false);
    // Navigate to video call room (e.g. `/call/roomId`)
    router.push("/call-room" /* or generate/join a unique room */);
  };

  const declineCall = () => {
    setShowCallPopup(false);
    socket.emit("decline_call", { to: incomingCall.id });
  };

  if (loading || !user) return <p>Loading chat…</p>;

  return (
    <div className="relative min-h-screen bg-gray-900 text-white p-4">
      {/* Chat header */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-3">
          <img
            src={receiver?.avatar}
            alt={receiver?.username}
            className="w-10 h-10 rounded-full object-cover"
          />
          <h2 className="text-xl font-semibold">{receiver?.username}</h2>
        </div>
        <button
          onClick={startCall}
          className="flex items-center gap-1 px-3 py-1 bg-green-600 hover:bg-green-700 rounded text-white"
        >
          <Video className="w-4 h-4" /> Call
        </button>
      </div>

      {/* Call Popup */}
      {showCallPopup && incomingCall && (
        <div className="absolute top-0 left-0 w-full h-full bg-black bg-opacity-70 flex items-center justify-center z-50">
          <div className="bg-white text-black p-6 rounded-xl w-80 text-center shadow-xl">
            <img
              src={incomingCall.avatar}
              alt={incomingCall.username}
              className="w-16 h-16 rounded-full mx-auto mb-2"
            />
            <p className="text-lg font-semibold">
              {incomingCall.username} is calling…
            </p>
            <div className="mt-4 flex justify-around">
              <button
                onClick={acceptCall}
                className="bg-green-500 px-4 py-2 rounded-lg text-white"
              >
                Accept
              </button>
              <button
                onClick={declineCall}
                className="bg-red-500 px-4 py-2 rounded-lg text-white"
              >
                Decline
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Chat messages + input would go here */}
      <div className="text-gray-400 mt-10">(Chat messages UI goes here)</div>
    </div>
  );
}
